<template>
  <div v-if="filters.length > 0" class="filter-badges-container">
    <div class="filter-badges-row">
      <q-badge
        v-for="filter in filters"
        :key="filter.column"
        color="primary"
        rounded
        class="filter-badge"
      >
        <span class="filter-badge-content">
          <span class="filter-badge-column">{{ getColumnLabel(filter.column) }}</span>
          <span class="filter-badge-operator">{{ $t(filter.operator) }}</span>
          <span class="filter-badge-value">"{{ filter.value }}"</span>
        </span>
        <q-icon
          name="close"
          color="white"
          size="xs"
          class="filter-badge-close"
          @click.stop="$emit('remove', filter.column)"
        />
      </q-badge>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import type { ColumnFilterValue, UnifiedTableColumn } from './types/table/unified-table';

export default defineComponent({
  name: 'FilterBadges',
  props: {
    /** Array of active filter values */
    filters: {
      type: Array as PropType<ColumnFilterValue[]>,
      required: true,
    },
    /** Column definitions for getting labels */
    columns: {
      type: Array as PropType<UnifiedTableColumn[]>,
      default: () => [],
    },
  },
  emits: ['remove', 'clear-all'],
  methods: {
    getColumnLabel(columnName: string): string {
      const column = this.columns.find((c) => c.name === columnName);
      if (column?.label) {
        // Try to translate the label
        try {
          const translated = this.$t(column.label);
          // If translation returns the key itself, use the raw label
          return translated === column.label ? column.label : String(translated);
        } catch {
          return column.label;
        }
      }
      // Fallback to column name with underscores replaced by spaces
      return columnName.replace(/_/g, ' ');
    },
  },
});
</script>

