<template>
  <!-- Trigger Button (optional - can be hidden if parent controls dialog) -->
  <q-btn
    v-if="showTriggerButton"
    square
    class="sub-menu-button"
    :color="buttonColor"
    :unelevated="buttonUnelevated"
    @click="openDialog"
  >
    <Icon :icon="buttonIcon" width="20" height="20" />
    <q-tooltip>{{ $t(tooltipKey) }}</q-tooltip>
  </q-btn>

  <!-- Column Settings Dialog -->
  <q-dialog
    v-model="dialogOpen"
    @show="onDialogShow"
    @hide="onDialogHide"
    @keydown.esc="dialogOpen = false"
  >
    <q-card class="column-settings-dialog">
      <!-- Header -->
      <q-toolbar class="text-white secondary-toolbar draggable-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('column_settings') }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section>
        <!-- Extra Actions Slot (e.g., "Add field from document type" button) -->
        <div v-if="$slots['extra-actions']" class="row justify-between items-center q-mb-md">
          <slot name="extra-actions" :visible-columns="visibleColumns" :hidden-columns="hiddenColumns" />
        </div>

        <!-- Two Column Layout -->
        <div class="row no-wrap justify-center q-pt-md q-gutter-md">
          <!-- Hidden Columns List -->
          <div class="drop-target rounded-borders">
            <div class="box row justify-center items-center position-sticky t-0 l-0 back-white z-index-1 column-header">
              {{ $t('hidden_columns') }}
            </div>
            <div class="search-column-card position-sticky l-0 back-white z-index-1">
              <q-input
                v-model="hiddenSearch"
                dense
                outlined
                autofocus
                :placeholder="$t('search_field')"
              />
            </div>
            <template v-for="(col, index) in filteredHiddenColumns" :key="col.name">
              <div
                :id="col.name"
                :data-column-name="col.name"
                class="box"
              >
                <q-checkbox
                  v-if="enableBatchSelection"
                  v-model="col.selected"
                  :data-column-name="col.name"
                />
                <span class="column-label" @click="!enableBatchSelection && showColumn(col)">
                  {{ getColumnLabel(col) }}
                </span>
                <q-btn
                  v-if="!enableBatchSelection"
                  flat
                  dense
                  round
                  size="xs"
                  icon="arrow_forward"
                  class="q-ml-auto"
                  @click="showColumn(col)"
                >
                  <q-tooltip>{{ $t('move_to_visibile_button_tooltip') }}</q-tooltip>
                </q-btn>
              </div>
            </template>
          </div>

          <!-- Middle Buttons (for batch selection mode) -->
          <div v-if="enableBatchSelection" class="rounded-borders overflow-hidden content-center middle-buttons">
            <div class="row justify-center items-center">
              <f-btn
                class="q-mb-sm"
                icon="arrow_back"
                @click="moveSelectedToHidden"
              >
                <q-tooltip>{{ $t('move_to_hidden_button_tooltip') }}</q-tooltip>
              </f-btn>
            </div>
            <div class="row justify-center items-center">
              <f-btn
                icon="arrow_forward"
                @click="moveSelectedToVisible"
              >
                <q-tooltip>{{ $t('move_to_visibile_button_tooltip') }}</q-tooltip>
              </f-btn>
            </div>
          </div>

          <!-- Visible Columns List -->
          <div class="drop-target rounded-borders">
            <div class="box row justify-center items-center position-sticky t-0 l-0 back-white z-index-1 column-header">
              {{ $t('visible_columns') }}
            </div>
            <div class="search-column-card position-sticky l-0 back-white z-index-1">
              <q-input
                v-model="visibleSearch"
                dense
                outlined
                :placeholder="$t('search_field')"
              />
            </div>
            <div class="visible-columns-parent">
              <template v-for="(col, index) in filteredVisibleColumns" :key="col.name">
                <div class="draggable-box">
                  <div
                    draggable="true"
                    :id="col.name"
                    :data-column-name="col.name"
                    :data-order="index"
                    class="box"
                    @dragstart="onDragStart($event, index, col)"
                    @dragover="onDragOver($event, index)"
                    @dragenter="onDragEnter($event)"
                    @dragleave="onDragLeave($event)"
                    @dragend="onDragEnd"
                    @drop="onDrop($event, index)"
                  >
                    <q-icon name="drag_indicator" size="xs" class="drag-handle" />
                    <q-checkbox
                      v-if="enableBatchSelection"
                      v-model="col.selected"
                      :data-column-name="col.name"
                      :data-order="index"
                      class="box-checkbox"
                    />
                    <!-- Custom column indicator (e.g., doc type field) -->
                    <q-icon
                      v-if="col.isCustomField || col.doc_type_key"
                      flat
                      dense
                      name="close"
                      size="24px"
                      color="red"
                      class="cursor-pointer"
                      @click="removeCustomColumn(col)"
                    >
                      <q-tooltip>{{ $t('remove_column') }}</q-tooltip>
                    </q-icon>
                    <span class="column-label">{{ getColumnLabel(col) }}</span>

                    <q-btn
                      v-if="!enableBatchSelection && !(col.isCustomField || col.doc_type_key)"
                      flat
                      dense
                      round
                      size="xs"
                      icon="visibility_off"
                      class="q-ml-auto"
                      @click="hideColumn(col)"
                    >
                      <q-tooltip>{{ $t('hide_column') }}</q-tooltip>
                    </q-btn>
                  </div>
                </div>
              </template>
            </div>
          </div>
        </div>

        <!-- Action Buttons -->
        <div class="row justify-end items-center q-mt-md q-gutter-sm">
          <f-btn
            v-if="showResetButton"
            appearance="secondary"
            :label="$t('reset')"
            @click="resetToDefault"
          />
          <f-btn
            appearance="cancel"
            :label="$t('cancel')"
            @click="cancelAndClose"
          />
          <f-btn
            :label="$t('done')"
            :loading="saving"
            @click="saveAndClose"
          />
        </div>
      </q-card-section>

      <!-- Loading Overlay -->
      <q-inner-loading :showing="saving">
        <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
      </q-inner-loading>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">

import { ref, nextTick, defineComponent, PropType } from 'vue';
import type { ColumnConfig, ColumnSettingsExposed } from './types/table/unified-table';

// Re-export types for backwards compatibility
export type { ColumnConfig, ColumnSettingsExposed };

export default defineComponent({
  name: 'ColumnSettings',
  
  props: {
    /** All available columns */
    columns: {
      type: Array as PropType<ColumnConfig[]>,
      required: true,
    },
    /**
     * Visible column objects - used directly preserving all column properties
     */
    visibleColumnObjects: {
      type: Object as PropType<Record<string, ColumnConfig>>,
      default: () => ({}),
    },
    /** Show the trigger button */
    showTriggerButton: {
      type: Boolean,
      default: true,
    },
    /** Button color */
    buttonColor: {
      type: String,
      default: 'primary',
    },
    /** Button icon */
    buttonIcon: {
      type: String,
      default: 'mdi:filter-variant',
    },
    /** Make button unelevated */
    buttonUnelevated: {
      type: Boolean,
      default: true,
    },
    /** Tooltip translation key */
    tooltipKey: {
      type: String,
      default: 'column_settings_tooltip',
    },
    /** Key to use for label lookup in column object */
    labelKey: {
      type: String,
      default: 'label',
    },
    /** Enable checkbox batch selection mode (like old component) */
    enableBatchSelection: {
      type: Boolean,
      default: true,
    },
    /** Show reset to default button */
    showResetButton: {
      type: Boolean,
      default: false,
    },
    /** Default columns for reset */
    defaultColumns: {
      type: Array as PropType<ColumnConfig[]>,
      default: () => [],
    },
    /** External loading state */
    loading: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['open', 'close', 'save', 'cancel', 'reset', 'remove-custom-column', 'columns-added'],
  setup(_, { expose }) {
    // State refs
    const dialogOpen = ref(false);
    const hiddenSearch = ref('');
    const visibleSearch = ref('');
    const saving = ref(false);
    const dragIndex = ref<number | null>(null);
    const visibleColumns = ref<ColumnConfig[]>([]);
    const hiddenColumns = ref<ColumnConfig[]>([]);
    const customColumns = ref<ColumnConfig[]>([]);

    // Expose is defined here but will reference methods from `this`
    // We use a trick: expose a wrapper that calls the real methods
    // The real expose happens in mounted()
    const exposeInterface = {
      open: null as unknown as () => void,
      close: null as unknown as () => void,
      setSaving: null as unknown as (value: boolean) => void,
      addColumns: null as unknown as (columns: ColumnConfig[]) => void,
      getVisibleColumns: null as unknown as () => ColumnConfig[],
      getHiddenColumns: null as unknown as () => ColumnConfig[],
    };

    expose(exposeInterface);

    return {
      dialogOpen,
      hiddenSearch,
      visibleSearch,
      saving,
      dragIndex,
      visibleColumns,
      hiddenColumns,
      customColumns,
      exposeInterface,
    };
  },
  computed: {
    filteredHiddenColumns(): ColumnConfig[] {
      if (!this.hiddenSearch) return this.hiddenColumns;
      const search = this.hiddenSearch.toLowerCase();
      return this.hiddenColumns.filter(col =>
        this.getColumnLabel(col).toLowerCase().includes(search) ||
        col.name.toLowerCase().includes(search)
      );
    },
    filteredVisibleColumns(): ColumnConfig[] {
      if (!this.visibleSearch) return this.visibleColumns;
      const search = this.visibleSearch.toLowerCase();
      return this.visibleColumns.filter(col =>
        this.getColumnLabel(col).toLowerCase().includes(search) ||
        col.name.toLowerCase().includes(search)
      );
    },
  },
  mounted() {
    // Wire up the exposed interface to the actual methods
    this.exposeInterface.open = this.openDialog;
    this.exposeInterface.close = this.closeDialog;
    this.exposeInterface.setSaving = this.setSaving;
    this.exposeInterface.addColumns = this.addColumns;
    this.exposeInterface.getVisibleColumns = () => this.visibleColumns;
    this.exposeInterface.getHiddenColumns = () => this.hiddenColumns;
  },
  methods: {
    /**
     * Get display label for a column
     */
    getColumnLabel(col: ColumnConfig): string {
      const label = col[this.labelKey] || col.label || col.name;
      return this.$t(label) || label;
    },
    /**
     * Initialize working columns from props
     * Uses visibleColumnObjects directly preserving all column properties
     */
    initializeColumns(): void {
      const addedNames = new Set<string>();

      // Get visible columns from object and sort by order
      const visibleObjects = Object.values(this.visibleColumnObjects || {}) as ColumnConfig[];
      const sortedVisible = [...visibleObjects].sort((a, b) => ((a as ColumnConfig).order ?? 0) - ((b as ColumnConfig).order ?? 0));

      this.visibleColumns = sortedVisible.map((col: ColumnConfig, index) => {
        addedNames.add(col.name);
        return {
          ...col,
          order: index,
          visible: true,
          selected: false,
          isCustomField: col.isCustomField || !!(col as ColumnConfig & { doc_type_key?: string }).doc_type_key,
        };
      });

      // Build hidden columns - base columns that are NOT in visible list
      this.hiddenColumns = this.columns
        .filter(col => !addedNames.has(col.name))
        .map(col => ({ ...col, visible: false, selected: false }));
    },
    /**
     * Move a single column to visible list
     */
    showColumn(col: ColumnConfig): void {
      const index = this.hiddenColumns.findIndex(c => c.name === col.name);
      if (index !== -1) {
        this.hiddenColumns.splice(index, 1);
      }
      col.visible = true;
      col.selected = false;
      col.order = this.visibleColumns.length;
      this.visibleColumns.push(col);
    },
    /**
     * Move a single column to hidden list
     */
    hideColumn(col: ColumnConfig): void {
      const index = this.visibleColumns.findIndex(c => c.name === col.name);
      if (index !== -1) {
        this.visibleColumns.splice(index, 1);
        // Update order for remaining columns
        this.visibleColumns.forEach((c, i) => c.order = i);
      }
      col.visible = false;
      col.selected = false;
      this.hiddenColumns.push(col);
    },
    /**
     * Move all selected hidden columns to visible (batch mode)
     */
    moveSelectedToVisible(): void {
      const selected = this.hiddenColumns.filter(c => c.selected);
      selected.forEach(col => {
        this.showColumn(col);
      });
    },
    /**
     * Move all selected visible columns to hidden (batch mode)
     */
    moveSelectedToHidden(): void {
      const selected = this.visibleColumns.filter(c => c.selected);
      selected.forEach(col => {
        this.hideColumn(col);
      });
    },
    /**
     * Remove a custom column (e.g., doc type field)
     */
    removeCustomColumn(col: ColumnConfig): void {
      // Remove from visible list
      const index = this.visibleColumns.findIndex(c => c.name === col.name);
      if (index !== -1) {
        this.visibleColumns.splice(index, 1);
        this.visibleColumns.forEach((c, i) => c.order = i);
      }

      // Also remove from custom columns tracker
      const customIndex = this.customColumns.findIndex(c => c.name === col.name);
      if (customIndex !== -1) {
        this.customColumns.splice(customIndex, 1);
      }

      // Don't add to hidden - it's being removed entirely
      this.$emit('remove-custom-column', col);
    },
    /**
     * Add columns (called from parent via slot or exposed method)
     */
    addColumns(columns: ColumnConfig[]): void {
      columns.forEach(col => {
        // Check if already exists
        const existsInVisible = this.visibleColumns.some(c => c.name === col.name);
        const existsInHidden = this.hiddenColumns.some(c => c.name === col.name);
        const existsInCustom = this.customColumns.some(c => c.name === col.name);

        if (!existsInVisible && !existsInHidden) {
          col.visible = true;
          col.selected = false;
          col.order = this.visibleColumns.length;
          this.visibleColumns.push(col);
        }

        // Track custom columns (e.g., doc type fields) so they persist across dialog reopens
        if (!existsInCustom && (col.isCustomField || col.doc_type_key)) {
          this.customColumns.push({ ...col });
        }
      });
      this.$emit('columns-added', columns);
    },
    // ============================================================================
    // DRAG & DROP
    // ============================================================================
    onDragStart(event: DragEvent, index: number, col: ColumnConfig): void {
      this.dragIndex = index;
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', String(index));
        event.dataTransfer.setData('column_name', col.name);
      }
      // Add visual feedback to the dragged element
      const target = event.target as HTMLElement;
      target.style.opacity = '0.4';
    },
    onDragOver(event: DragEvent, index: number): void {
      event.preventDefault();
      if (this.dragIndex === null || this.dragIndex === index) return;

      // Reorder columns
      const item = this.visibleColumns[this.dragIndex];
      this.visibleColumns.splice(this.dragIndex, 1);
      this.visibleColumns.splice(index, 0, item);

      // Update order properties
      this.visibleColumns.forEach((col, i) => col.order = i);
      this.dragIndex = index;
    },
    onDragEnter(event: DragEvent): void {
      // Find the .box element (might be the target or a parent)
      const target = event.target as HTMLElement;
      const boxEl = target.closest('.box') as HTMLElement;
      boxEl?.classList.add('over');
    },
    onDragLeave(event: DragEvent): void {
      const target = event.target as HTMLElement;
      const boxEl = target.closest('.box') as HTMLElement;
      boxEl?.classList.remove('over');
    },
    onDragEnd(): void {
      this.dragIndex = null;
      // Reset opacity on all draggable boxes
      document.querySelectorAll('.visible-columns-parent .box').forEach(el => {
        (el as HTMLElement).style.opacity = '1';
      });
      // Remove over class from all elements
      document.querySelectorAll('.over').forEach(el => el.classList.remove('over'));
    },
    onDrop(event: DragEvent, _index: number): void {
      event.preventDefault();
      event.stopPropagation();
      this.onDragEnd();
    },
    // ============================================================================
    // DIALOG ACTIONS
    // ============================================================================
    openDialog(): void {
      this.dialogOpen = true;
    },
    async onDialogShow(): Promise<void> {
      this.hiddenSearch = '';
      this.visibleSearch = '';
      // Emit 'open' first so parent can prepare/load the data
      this.$emit('open');
      // Wait for parent to update props with the actual visible column names
      await nextTick();
      // Small additional delay for async operations in parent
      await new Promise(resolve => setTimeout(resolve, 100));
      // Now initialize with the updated props
      this.initializeColumns();
    },
    onDialogHide(): void {
      this.hiddenSearch = '';
      this.visibleSearch = '';
      this.$emit('close');
    },
    resetToDefault(): void {
      if (this.defaultColumns.length > 0) {
        // Use provided defaults
        const defaultVisible = this.defaultColumns.filter(c => c.visible !== false);
        const defaultHidden = this.defaultColumns.filter(c => c.visible === false);

        this.visibleColumns = defaultVisible.map((col, index) => ({
          ...col,
          order: index,
          visible: true,
          selected: false
        }));
        this.hiddenColumns = defaultHidden.map(col => ({
          ...col,
          visible: false,
          selected: false
        }));
      } else {
        this.initializeColumns();
      }
      this.$emit('reset');
    },
    cancelAndClose(): void {
      this.dialogOpen = false;
      this.$emit('cancel');
    },
    saveAndClose(): void {
      this.saving = true;

      // Prepare final column data
      const visibleColumns = this.visibleColumns.map((col, index) => ({
        ...col,
        order: index,
        visible: true,
        selected: undefined // Remove internal state
      }));

      const hiddenColumns = this.hiddenColumns.map(col => ({
        ...col,
        visible: false,
        selected: undefined
      }));

      const allColumns = [...visibleColumns, ...hiddenColumns];

      this.$emit('save', { visibleColumns, hiddenColumns, allColumns });

      // Note: Parent should call closeDialog() after successful save
      // Or set saving = false if save fails
    },
    /**
     * Close dialog (called by parent after save completes)
     */
    closeDialog(): void {
      this.saving = false;
      this.dialogOpen = false;
    },
    /**
     * Set saving state (called by parent if save fails)
     */
    setSaving(value: boolean): void {
      this.saving = value;
    },
  },
});
</script>

