<template>
  <div class="bulk-actions-menu" @click.stop>
    <q-btn
      flat
      dense
      round
      icon="more_vert"
      :disable="disabled"
      :aria-label="$t('bulk_actions_menu')"
      aria-haspopup="menu"
      :aria-expanded="menuOpen ? 'true' : 'false'"
      :aria-disabled="disabled"
    >
      <q-menu
        v-model="menuOpen"
        auto-close
        transition-show="jump-down"
        transition-hide="jump-up"
        :offset="[0, 5]"
        anchor="bottom left"
        self="top left"
        role="menu"
        :aria-label="$t('bulk_actions_menu')"
      >
        <q-list dense class="bulk-actions-list" role="menubar">
          <template v-for="(action, index) in visibleActions" :key="action.key">
            <!-- Separator before action if specified -->
            <q-separator v-if="action.separator && index > 0" inset role="separator" />

            <!-- Action Item -->
            <q-item
              clickable
              v-close-popup
              :disable="isActionDisabled(action)"
              role="menuitem"
              :aria-label="$t(action.label)"
              :aria-disabled="isActionDisabled(action)"
              @click="emitAction(action.key)"
            >
              <q-item-section v-if="action.icon" avatar class="list-avatar">
                <q-icon
                  :name="action.icon"
                  :color="isSvgIcon(action.icon) ? undefined : (action.color || 'grey-7')"
                  size="xs"
                  style="font-size: 14px"
                  :class="[
                    action.iconClass,
                    {
                      'svg-action-icon': isSvgIcon(action.icon) && !action.color && !action.iconClass,
                    },
                  ]"
                  aria-hidden="true"
                />
              </q-item-section>
              <q-item-section :class="action.color === 'negative' ? 'text-negative' : ''">
                {{ $t(action.label) }}
              </q-item-section>
              <!-- Tooltip explaining why action is disabled -->
              <q-tooltip v-if="getActionDisabledReason(action)">
                {{ getActionDisabledReason(action) }}
              </q-tooltip>
            </q-item>
          </template>

          <!-- Empty state if no actions -->
          <q-item v-if="visibleActions.length === 0" disable aria-disabled="true">
            <q-item-section class="text-grey-6 text-center">
              No actions available
            </q-item-section>
          </q-item>
        </q-list>
      </q-menu>
    </q-btn>
  </div>
</template>

<script lang="ts">
import { ref, defineComponent, PropType } from 'vue';
import type { BulkActionItem } from './types/table/unified-table';

export default defineComponent({
  name: 'BulkActionsMenu',
  props: {
    /** Array of bulk action configurations */
    actions: {
      type: Array as PropType<BulkActionItem[]>,
      required: true,
    },
    /** Number of rows currently selected */
    selectedCount: {
      type: Number,
      required: true,
    },
    /** Array of selected row data (for show conditions) */
    selectedRows: {
      type: Array as PropType<any[]>,
      default: () => [],
    },
    /** Whether the menu should be disabled */
    disabled: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['action'],
  setup() {
    return {
      menuOpen: ref(false),
    };
  },
  computed: {
    visibleActions(): BulkActionItem[] {
      return this.actions.filter((action) => {
        if (!action.show) return true;
        return action.show(this.selectedRows, this.selectedCount);
      });
    },
  },
  methods: {
    isActionDisabled(action: BulkActionItem): boolean {
      if (action.minSelected !== undefined && this.selectedCount < action.minSelected) {
        return true;
      }
      if (action.maxSelected !== undefined && this.selectedCount > action.maxSelected) {
        return true;
      }
      return false;
    },
    getActionDisabledReason(action: BulkActionItem): string | undefined {
      if (action.minSelected !== undefined && this.selectedCount < action.minSelected) {
        return `Requires at least ${action.minSelected} selected row${action.minSelected > 1 ? 's' : ''}`;
      }
      if (action.maxSelected !== undefined && this.selectedCount > action.maxSelected) {
        return `Requires at most ${action.maxSelected} selected row${action.maxSelected > 1 ? 's' : ''}`;
      }
      return undefined;
    },
    // Check if icon is an SVG (starts with "img:")
    isSvgIcon(icon: string): boolean {
      return icon?.startsWith('img:') || false;
    },
    // Wrapper method for emitting action
    emitAction(key: string): void {
      this.$emit('action', key);
    },
  },
});
</script>

<style lang="scss">
// Compact menu styling to match RowActionsMenu
.bulk-actions-list {
  min-width: 100px !important;

  .list-avatar {
    min-width: auto;
  }
}

