    // But keep negative colored icons red
    .q-icon.text-negative {
      color: var(--q-negative) !important;
    }
  }
}

// Dark mode styling
.body--dark {
  // Ensure menu button icon is visible
  .bulk-actions-menu {
    .q-btn .q-icon {
      color: var(--dashboard-text-color, #b0b0b0);
    }
  }

  // Ensure SVG icons are white (visible on dark menu background)
  .bulk-actions-list {
    .svg-action-icon img {
      filter: brightness(0) invert(1);
    }

    // Ensure Material icons are white in dark mode (override grey-7)
    .q-icon {
      color: #ffffff !important;
    }

    // But keep negative colored icons red
    .q-icon.text-negative {
      color: var(--q-negative) !important;
    }
  }
}
</style>
